"""Tipos compartilhados entre leitores, regras e gravador (CONTRATO_TECNICO_MINIMO.md, seção 3).

Dono: B. Publicado por A, copiando o contrato, para destravar o desenvolvimento em paralelo;
qualquer mudança de interface deve ser combinada entre A e B.
"""
from __future__ import annotations

from decimal import Decimal
from typing import Literal, NotRequired, TypedDict

from src.core.saida import Origem  # noqa: F401  (reexportado: não duplicar o tipo)


class TransacaoOrbe(TypedDict):
    id_transacao: str
    data_movimento: str  # ISO AAAA-MM-DD
    ec: str
    nome_origem: str
    tipo_lancamento: str  # preserva o enum da fonte
    modalidade: str | None
    qtd_parcelas: int | None
    valor_bruto: Decimal  # mantém o sinal da fonte
    taxa_aplicada_pct: Decimal
    arquivo_origem: str
    ref_origem: str  # igual a id_transacao
    # campos extras preservados da fonte (não usados no nível Mínimo)
    bandeira: NotRequired[str | None]
    valor_taxa: NotRequired[Decimal | None]
    valor_liquido: NotRequired[Decimal | None]
    id_referencia: NotRequired[str | None]
    data_venda_original: NotRequired[str | None]


class TaxasContrato(TypedDict):
    DEBITO: Decimal | None
    CREDITO_A_VISTA: Decimal | None
    CREDITO_2_6: Decimal | None
    CREDITO_7_12: Decimal | None
    PIX: Decimal | None


class ContratoTaxa(TypedDict):
    cnpj: str
    lojista: str
    ec: str | None
    ativo: bool
    vigencia_inicio: str | None  # ISO
    vigencia_fim: str | None  # ISO
    taxas_pct: TaxasContrato
    arquivo_origem: str
    ref_origem: str


class ComissaoCalculada(TypedDict):
    cnpj: str
    lojista: str
    linha_negocio: Literal["CHECKOUT"]
    comissao_brl: Decimal  # soma das comissões arredondadas por venda
    origens: list[Origem]  # contribuição com duas casas por venda
    contratos_utilizados: list[dict[str, str]]  # {"arquivo_origem", "ref_origem"}


class PendenciaCalculada(TypedDict):
    tipo: str
    ref_origem: str
    valor_brl: Decimal
    motivo: str
    quem_decide: Literal["Financeiro", "Comercial"]
    origens: list[Origem]


class ResumoCheckout(TypedDict):
    total_orbe: int
    vendas_total: int
    vendas_processadas: int
    vendas_bloqueadas: int
    fora_escopo_por_tipo: dict[str, int]
    contagens_por_arquivo: dict[str, int]


class ResultadoCheckout(TypedDict):
    comissoes: list[ComissaoCalculada]
    pendencias: list[PendenciaCalculada]
    resumo: ResumoCheckout
"""Contrato comum de saída: todo número emitido carrega suas origens e a soma é conferida.

Uso:
    saida = Saida()
    id_ = saida.emitir(
        "comissoes_por_lojista",
        {"cnpj": "...", "lojista": "...", "linha_negocio": "CHECKOUT", "comissao_brl": Decimal("16.37")},
        origens=[Origem("01_orbe_relatorio_comissoes_set2026.csv", "TX88410932", Decimal("16.37"))],
    )
    saida.gravar("saida/")

Regra de arredondamento (plano, seção 3): quem emite passa o valor de cada linha de origem **já
na regra de negócio** (ex.: comissão da transação); `emitir` arredonda cada origem e o valor
reportado a 2 casas com ROUND_HALF_UP e **falha** se Σ rastro != valor reportado. Assim o rastro
leva os mesmos valores arredondados por linha e a soma bate ao centavo.
"""
from __future__ import annotations

import csv
import re
from dataclasses import dataclass
from decimal import Decimal
from pathlib import Path

from src.core.normalize import q2

LINHAS_NEGOCIO = ("CHECKOUT", "REMESSA")
BANCOS = ("AURORA", "MERIDIANO")
METODOS = ("REGRA", "IA", "HUMANO")


class SaidaError(ValueError):
    """Violação do contrato de saída (coluna, formato, enum ou soma do rastro)."""


@dataclass(frozen=True)
class Origem:
    arquivo: str
    ref: str
    valor: Decimal


@dataclass(frozen=True)
class Esquema:
    prefixo: str
    colunas: tuple[str, ...]  # obrigatórias, na ordem do enunciado
    extras: tuple[str, ...] = ()  # colunas extras permitidas (opcionais)
    valor: str | None = None  # coluna que carrega o valor conferido contra o rastro
    pct: tuple[str, ...] = ()  # colunas em pontos percentuais
    cnpj: tuple[str, ...] = ()
    datas: tuple[str, ...] = ()
    enums: tuple[tuple[str, tuple[str, ...]], ...] = ()
    textos: tuple[str, ...] = ()  # obrigatoriamente não vazias


ESQUEMAS: dict[str, Esquema] = {
    "comissoes_por_lojista": Esquema(
        "COM", ("id_saida", "cnpj", "lojista", "linha_negocio", "comissao_brl"),
        valor="comissao_brl", cnpj=("cnpj",),
        enums=(("linha_negocio", LINHAS_NEGOCIO),), textos=("lojista",),
    ),
    "divergencias_taxa": Esquema(
        "DIV",
        ("id_saida", "cnpj", "linha_negocio", "ref_origem", "taxa_contratada_pct",
         "taxa_aplicada_pct", "diferenca_brl"),
        valor="diferenca_brl", pct=("taxa_contratada_pct", "taxa_aplicada_pct"), cnpj=("cnpj",),
        enums=(("linha_negocio", LINHAS_NEGOCIO),), textos=("ref_origem",),
    ),
    "notas_a_emitir": Esquema(
        "NF", ("id_saida", "tomador_cnpj", "tomador", "linha_negocio", "valor_brl", "discriminacao"),
        valor="valor_brl", cnpj=("tomador_cnpj",),
        enums=(("linha_negocio", LINHAS_NEGOCIO),), textos=("tomador", "discriminacao"),
    ),
    "lancamentos_classificados": Esquema(
        "LAN",
        ("id_saida", "banco", "ref_origem", "data", "descricao", "valor", "conta_codigo",
         "metodo", "confianca"),
        valor="valor", pct=("confianca",), datas=("data",),
        enums=(("banco", BANCOS), ("metodo", METODOS)),
        textos=("ref_origem", "descricao", "conta_codigo"),
    ),
    "pendencias": Esquema(
        "PEN", ("id_saida", "tipo", "ref_origem", "valor_brl", "motivo", "quem_decide"),
        extras=("sugestao",), valor="valor_brl", textos=("tipo", "motivo", "quem_decide"),
    ),
    # O rastro é escrito por `emitir`; não se emite linha de rastro diretamente.
    "rastro": Esquema("", ("id_saida", "arquivo_origem", "ref_origem", "valor")),
}

ARQUIVOS_EMISSIVEIS = tuple(n for n, e in ESQUEMAS.items() if e.prefixo)


def _fmt_decimal(d: Decimal, min_casas: int = 2) -> str:
    """Decimal em ponto fixo (sem notação científica), com no mínimo `min_casas` casas."""
    s = format(d.normalize(), "f")
    casas = len(s.split(".")[1]) if "." in s else 0
    return s if casas >= min_casas else format(d.quantize(Decimal(1).scaleb(-min_casas)), "f")


def _como_decimal(coluna: str, v) -> Decimal:
    if isinstance(v, bool) or v is None:
        raise SaidaError(f"{coluna}: valor numérico obrigatório, veio {v!r}")
    if isinstance(v, float):
        raise SaidaError(f"{coluna}: float não permitido, use Decimal (veio {v!r})")
    try:
        numero = Decimal(v)
    except Exception:
        raise SaidaError(f"{coluna}: número inválido {v!r}") from None
    if not numero.is_finite():
        raise SaidaError(f"{coluna}: número deve ser finito (veio {v!r})")
    return numero


class Saida:
    """Acumula linhas de saída + rastro; `gravar` escreve os 6 CSVs."""

    def __init__(self) -> None:
        self._linhas: dict[str, list[dict[str, str]]] = {n: [] for n in ESQUEMAS}
        self._contadores: dict[str, int] = {}

    def emitir(self, arquivo: str, linha: dict, origens: list[Origem | tuple]) -> str:
        """Valida a linha, gera `id_saida`, registra o rastro e devolve o id.

        `linha` não leva `id_saida` (gerado aqui). `origens`: Origem ou tupla (arquivo, ref, valor).
        """
        if arquivo not in ARQUIVOS_EMISSIVEIS:
            raise SaidaError(f"arquivo de saída desconhecido: {arquivo!r}")
        esq = ESQUEMAS[arquivo]
        if "id_saida" in linha:
            raise SaidaError("id_saida é gerado por emitir(); não informe")

        permitidas = set(esq.colunas) - {"id_saida"} | set(esq.extras)
        faltando = (set(esq.colunas) - {"id_saida"}) - set(linha)
        sobrando = set(linha) - permitidas
        if faltando:
            raise SaidaError(f"{arquivo}: faltam colunas {sorted(faltando)}")
        if sobrando:
            raise SaidaError(f"{arquivo}: colunas não previstas {sorted(sobrando)}")

        campos = {c: self._validar(arquivo, esq, c, linha[c]) for c in linha}
        valor = q2(_como_decimal(esq.valor, linha[esq.valor]))
        campos[esq.valor] = _fmt_decimal(valor)

        itens = [o if isinstance(o, Origem) else Origem(*o) for o in origens]
        rastro = [(o, q2(_como_decimal("origem.valor", o.valor))) for o in itens]
        for o, _ in rastro:
            if not o.arquivo or not o.ref:
                raise SaidaError(f"{arquivo}: origem sem arquivo/ref ({o!r})")
        if not rastro and valor != 0:
            raise SaidaError(f"{arquivo}: valor {valor} sem nenhuma origem no rastro")
        soma = sum((v for _, v in rastro), Decimal(0))
        if soma != valor:
            raise SaidaError(
                f"{arquivo}: Σ rastro ({soma}) != valor reportado ({valor}) "
                f"[{', '.join(o.ref for o, _ in rastro)}]"
            )

        self._contadores[arquivo] = self._contadores.get(arquivo, 0) + 1
        id_saida = f"{esq.prefixo}-{self._contadores[arquivo]:04d}"
        self._linhas[arquivo].append({"id_saida": id_saida, **campos})
        for o, v in rastro:
            self._linhas["rastro"].append(
                {"id_saida": id_saida, "arquivo_origem": o.arquivo, "ref_origem": o.ref,
                 "valor": _fmt_decimal(v)}
            )
        return id_saida

    @staticmethod
    def _validar(arquivo: str, esq: Esquema, col: str, v) -> str:
        if col == esq.valor:
            return ""  # preenchido por emitir() após o arredondamento
        if col in esq.pct:
            d = _como_decimal(col, v)
            if col == "confianca" and not Decimal(0) <= d <= Decimal(1):
                raise SaidaError(f"{arquivo}.{col}: deve estar entre 0 e 1 (veio {d})")
            return _fmt_decimal(d)
        s = "" if v is None else str(v)
        if col in esq.cnpj and not re.fullmatch(r"\d{14}", s):
            raise SaidaError(f"{arquivo}.{col}: CNPJ deve ter 14 dígitos (veio {s!r})")
        if col in esq.datas and not re.fullmatch(r"\d{4}-\d{2}-\d{2}", s):
            raise SaidaError(f"{arquivo}.{col}: data deve ser AAAA-MM-DD (veio {s!r})")
        for c, validos in esq.enums:
            if col == c and s not in validos:
                raise SaidaError(f"{arquivo}.{col}: {s!r} fora de {validos}")
        if col in esq.textos and not s.strip():
            raise SaidaError(f"{arquivo}.{col}: não pode ser vazio")
        return s

    def gravar(self, destino: str | Path) -> dict[str, Path]:
        """Escreve os 6 CSVs em `destino` (`;`, UTF-8, `\\n`) e reconfere a soma do rastro."""
        destino = Path(destino)
        destino.mkdir(parents=True, exist_ok=True)
        caminhos = {}
        for nome, esq in ESQUEMAS.items():
            colunas = list(esq.colunas) + [
                c for c in esq.extras if any(c in r for r in self._linhas[nome])
            ]
            caminho = destino / f"{nome}.csv"
            with caminho.open("w", newline="", encoding="utf-8") as f:
                w = csv.DictWriter(f, fieldnames=colunas, delimiter=";", lineterminator="\n",
                                   restval="")
                w.writeheader()
                w.writerows(self._linhas[nome])
            caminhos[nome] = caminho
        conferir_diretorio(destino)
        return caminhos


def conferir_diretorio(pasta: str | Path) -> None:
    """Relê os CSVs em disco e exige Σ rastro.valor por id_saida == valor reportado.

    Levanta SaidaError com a lista de ids que não fecham. Também falha se o rastro citar um
    id inexistente ou se um id de saída com valor != 0 não tiver rastro.
    """
    pasta = Path(pasta)

    def ler(nome: str) -> list[dict[str, str]]:
        with (pasta / f"{nome}.csv").open(newline="", encoding="utf-8") as f:
            return list(csv.DictReader(f, delimiter=";"))

    soma_rastro: dict[str, Decimal] = {}
    for r in ler("rastro"):
        soma_rastro[r["id_saida"]] = soma_rastro.get(r["id_saida"], Decimal(0)) + Decimal(r["valor"])

    erros, vistos = [], set()
    for nome in ARQUIVOS_EMISSIVEIS:
        col = ESQUEMAS[nome].valor
        for r in ler(nome):
            vistos.add(r["id_saida"])
            reportado, rastreado = Decimal(r[col]), soma_rastro.get(r["id_saida"], Decimal(0))
            if reportado != rastreado:
                erros.append(f"{r['id_saida']}: reportado {reportado} != rastro {rastreado}")
    erros += [f"{i}: rastro sem linha de saída" for i in sorted(set(soma_rastro) - vistos)]
    if erros:
        raise SaidaError("rastro não fecha:\n  " + "\n  ".join(erros))
"""Normalização de tipos vindos das fontes (CNPJ, dinheiro, percentual, data).

Convenções de saída:
- dinheiro e percentual são `Decimal` (nunca float);
- percentual é sempre em **pontos percentuais** (2,59 = 2,59%): a Orbe já vem assim,
  a planilha de taxas vem em fração e é convertida aqui antes de qualquer comparação;
- data é `AAAA-MM-DD` (str).
"""
from __future__ import annotations

import re
from datetime import date, datetime, timedelta
from decimal import ROUND_HALF_UP, Decimal, InvalidOperation

CENTAVO = Decimal("0.01")
# Excel (sistema 1900): serial 1 = 1900-01-01, com o bug do 29/02/1900 -> época efetiva 1899-12-30.
_EPOCA_EXCEL = date(1899, 12, 30)


def _vazio(x) -> bool:
    if x is None:
        return True
    if isinstance(x, float) and x != x:  # NaN
        return True
    return isinstance(x, str) and not x.strip()


def q2(valor: Decimal) -> Decimal:
    """Arredonda a 2 casas com ROUND_HALF_UP (o `round()` do Python arredonda para o par)."""
    return Decimal(valor).quantize(CENTAVO, rounding=ROUND_HALF_UP)


def cnpj(x) -> str | None:
    """Só dígitos, 14 posições. Aceita pontuado, texto, int e float (Excel perde o zero à esquerda).

    Devolve None para vazio. Levanta ValueError se sobrar mais de 14 dígitos ou nenhum.
    """
    if _vazio(x):
        return None
    if isinstance(x, float):
        if x != int(x):
            raise ValueError(f"CNPJ inválido: {x!r}")
        x = int(x)
    digitos = re.sub(r"\D", "", str(x))
    if not digitos or len(digitos) > 14:
        raise ValueError(f"CNPJ inválido: {x!r}")
    return digitos.zfill(14)


def _decimal_ptbr(texto: str) -> Decimal:
    t = texto.strip().replace("R$", "").replace(" ", "")
    if "," in t:  # pt-BR: ponto é milhar, vírgula é decimal
        t = t.replace(".", "").replace(",", ".")
    try:
        return Decimal(t)
    except InvalidOperation:
        raise ValueError(f"número inválido: {texto!r}") from None


def brl(x) -> Decimal | None:
    """Dinheiro: `"1.234,56"` -> Decimal('1234.56'); aceita negativo, int, float e Decimal.

    Texto sem vírgula é lido como decimal com ponto (`"1234.56"`). Vazio -> None.
    """
    if _vazio(x):
        return None
    if isinstance(x, Decimal):
        return x
    if isinstance(x, (int, float)):
        return Decimal(str(x))
    return _decimal_ptbr(str(x))


def pct(x, fracao: bool = True) -> Decimal | None:
    """Percentual em **pontos percentuais**.

    - texto com `%` (`'2,59%'`) -> sempre pontos: 2.59;
    - número/texto sem `%`: se `fracao=True` (planilha: 0.0259) multiplica por 100;
      se `fracao=False` (Orbe: `'2,69'`) já está em pontos.
    """
    if _vazio(x):
        return None
    if isinstance(x, str) and "%" in x:
        return _decimal_ptbr(x.replace("%", ""))
    valor = brl(x)
    return valor * 100 if fracao else valor


def data(x) -> str | None:
    """Data -> `AAAA-MM-DD`. Aceita `dd/mm/aaaa`, ISO, date/datetime e serial Excel (int/float/texto)."""
    if _vazio(x):
        return None
    if isinstance(x, datetime):
        return x.date().isoformat()
    if isinstance(x, date):
        return x.isoformat()
    if isinstance(x, (int, float)):
        return (_EPOCA_EXCEL + timedelta(days=int(x))).isoformat()
    t = str(x).strip()
    if re.fullmatch(r"\d+(\.\d+)?", t):
        return (_EPOCA_EXCEL + timedelta(days=int(float(t)))).isoformat()
    if re.fullmatch(r"\d{2}/\d{2}/\d{4}", t):
        return datetime.strptime(t, "%d/%m/%Y").date().isoformat()
    if re.fullmatch(r"\d{4}-\d{2}-\d{2}", t):
        return datetime.strptime(t, "%Y-%m-%d").date().isoformat()
    raise ValueError(f"data inválida: {x!r}")
"""CLI do nível mínimo: leitores e cálculo de A, publicação e conservação de B."""
from __future__ import annotations

import argparse
from collections import Counter
from datetime import date
from pathlib import Path
import re
from tempfile import TemporaryDirectory

import yaml

from src.core.contratos import ResultadoCheckout
from src.core.saida import Saida
from src.regras.pendencias import validar_pendencia

RAIZ = Path(__file__).resolve().parent.parent


def _carregar_yaml(caminho: Path) -> dict:
    with caminho.open(encoding="utf-8") as arquivo:
        conteudo = yaml.safe_load(arquivo)
    if not isinstance(conteudo, dict):
        raise ValueError(f"{caminho}: esperado mapa YAML")
    return conteudo


def _validar_competencia(competencia: str) -> None:
    if not re.fullmatch(r"[0-9]{4}-[0-9]{2}", competencia):
        raise ValueError("competência deve ter formato AAAA-MM")
    date.fromisoformat(f"{competencia}-01")


def _componentes_checkout():
    # Importação adiada permite usar --help antes de integrar a entrega de A.
    try:
        from src.ingest.orbe import ler_orbe
        from src.ingest.taxas import ler_taxas
        from src.regras.checkout import calcular_checkout
    except ModuleNotFoundError as erro:
        if erro.name in ("src.ingest.orbe", "src.ingest.taxas", "src.regras.checkout"):
            raise ValueError(f"Integração depende da entrega do membro A: {erro.name}") from erro
        raise
    return ler_orbe, ler_taxas, calcular_checkout


def _conferir_conservacao(transacoes, resultado):
    vendas = {t["ref_origem"]: t for t in transacoes if t["tipo_lancamento"] == "VENDA"}
    if len({t["id_transacao"] for t in transacoes}) != len(transacoes):
        raise ValueError("Orbe contém id_transacao repetido")
    processadas, bloqueadas = [], []
    for comissao in resultado["comissoes"]:
        if comissao["linha_negocio"] != "CHECKOUT":
            raise ValueError("Nível mínimo permite somente CHECKOUT")
        processadas.extend(comissao["origens"])
    for pendencia in resultado["pendencias"]:
        validar_pendencia(pendencia)
        origens_venda = [o for o in pendencia["origens"] if o.ref in vendas
                         and o.arquivo == vendas[o.ref]["arquivo_origem"]]
        if origens_venda:
            if len(origens_venda) != 1 or len(pendencia["origens"]) != 1:
                raise ValueError("Venda bloqueada exige uma pendência com uma origem")
            origem = origens_venda[0]
            if origem.valor != vendas[origem.ref]["valor_bruto"]:
                raise ValueError("Pendência de venda deve rastrear o bruto assinado")
            bloqueadas.extend(origens_venda)
        elif pendencia["valor_brl"] != 0:
            raise ValueError("Pendência cadastral deve ter valor zero")
    esperadas = Counter((t["arquivo_origem"], t["ref_origem"]) for t in vendas.values())
    recebidas = Counter((o.arquivo, o.ref) for o in processadas + bloqueadas)
    if esperadas != recebidas:
        raise ValueError("Conservação: cada venda deve aparecer exatamente uma vez na saída")
    cnpjs = [c["cnpj"] for c in resultado["comissoes"]]
    if len(set(cnpjs)) != len(cnpjs):
        raise ValueError("Comissão deve ter uma linha por CNPJ")
    esperado = {
        "total_orbe": len(transacoes), "vendas_total": len(vendas),
        "vendas_processadas": len(processadas), "vendas_bloqueadas": len(bloqueadas),
        "fora_escopo_por_tipo": dict(Counter(t["tipo_lancamento"] for t in transacoes
                                             if t["tipo_lancamento"] != "VENDA")),
        "contagens_por_arquivo": dict(Counter(t["arquivo_origem"] for t in transacoes)),
    }
    if resultado["resumo"] != esperado:
        raise ValueError(f"Resumo não conserva as entradas; esperado: {esperado}")


def run(entrada: Path, competencia: str, saida: Path,
        regras_path: Path, cadastro_path: Path) -> ResultadoCheckout:
    _validar_competencia(competencia)
    entrada, saida = Path(entrada).resolve(), Path(saida).resolve()
    if not entrada.is_dir():
        raise ValueError(f"Pasta de entrada inexistente: {entrada}")
    regras = _carregar_yaml(Path(regras_path))
    cadastro = _carregar_yaml(Path(cadastro_path)).get("lojistas")
    if not isinstance(cadastro, dict):
        raise ValueError("Cadastro deve conter o mapa lojistas")
    if not isinstance(regras.get("checkout"), dict):
        raise ValueError("Regras devem conter o mapa checkout")
    arquivos_taxas = sorted(entrada.glob("02_*.xlsx"))
    if len(arquivos_taxas) != 1:
        raise ValueError("Esperado exatamente um arquivo de taxas 02_*.xlsx na entrada")
    ler_orbe, ler_taxas, calcular_checkout = _componentes_checkout()
    transacoes = ler_orbe(entrada)
    for transacao in transacoes:
        data = date.fromisoformat(transacao["data_movimento"])
        if data.isoformat()[:7] != competencia:
            raise ValueError(f"Transação {transacao['id_transacao']} fora da competência {competencia}")
    contratos = ler_taxas(arquivos_taxas[0])
    resultado = calcular_checkout(transacoes, contratos, cadastro, competencia, regras)
    _conferir_conservacao(transacoes, resultado)
    gravador = Saida()
    for comissao in sorted(resultado["comissoes"], key=lambda c: c["cnpj"]):
        gravador.emitir("comissoes_por_lojista", {k: v for k, v in comissao.items()
                       if k not in ("origens", "contratos_utilizados")}, comissao["origens"])
    for pendencia in sorted(resultado["pendencias"], key=lambda p:
                            (p["tipo"], p["origens"][0].arquivo, p["ref_origem"])):
        gravador.emitir("pendencias", {k: v for k, v in pendencia.items() if k != "origens"},
                       pendencia["origens"])
    # Só publica depois de gravar e reconferir todos os CSVs em disco.
    saida.parent.mkdir(parents=True, exist_ok=True)
    with TemporaryDirectory(prefix=".fechamento-", dir=saida.parent) as temporaria:
        caminhos = gravador.gravar(temporaria)
        saida.mkdir(parents=True, exist_ok=True)
        for caminho in caminhos.values():
            caminho.replace(saida / caminho.name)
    resumo = resultado["resumo"]
    print(f"Orbe: {resumo['total_orbe']} linhas; vendas: {resumo['vendas_total']} = "
          f"{resumo['vendas_processadas']} processadas + {resumo['vendas_bloqueadas']} bloqueadas")
    for arquivo, quantidade in sorted(resumo["contagens_por_arquivo"].items()):
        print(f"  {arquivo}: {quantidade} linhas")
    for tipo, quantidade in sorted(resumo["fora_escopo_por_tipo"].items()):
        print(f"  {tipo}: {quantidade} fora do escopo deste nível")
    return resultado


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description="Fechamento mínimo de checkout (somente vendas)")
    parser.add_argument("--entrada", type=Path, required=True)
    parser.add_argument("--competencia", required=True)
    parser.add_argument("--saida", type=Path, required=True)
    parser.add_argument("--regras", type=Path, default=RAIZ / "config/regras.yaml")
    parser.add_argument("--cadastro", type=Path, default=RAIZ / "config/lojistas.yaml")
    args = parser.parse_args(argv)
    try:
        run(args.entrada, args.competencia, args.saida, args.regras, args.cadastro)
    except (OSError, ValueError, yaml.YAMLError) as erro:
        parser.exit(1, f"Erro: {erro}\n")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
"""Validação estrutural de pendências; decisões de negócio pertencem ao cálculo."""
from decimal import Decimal
from pathlib import PurePosixPath, PureWindowsPath

from src.core.contratos import PendenciaCalculada
from src.core.saida import Origem, SaidaError


def validar_pendencia(pendencia: PendenciaCalculada) -> None:
    for campo in ("tipo", "ref_origem", "motivo", "quem_decide"):
        valor = pendencia.get(campo)
        if not isinstance(valor, str) or not valor.strip():
            raise SaidaError(f"pendência.{campo}: texto obrigatório")
    if pendencia["quem_decide"] not in ("Financeiro", "Comercial"):
        raise SaidaError("pendência.quem_decide: use Financeiro ou Comercial")
    valor = pendencia.get("valor_brl")
    if not isinstance(valor, Decimal) or not valor.is_finite():
        raise SaidaError("pendência.valor_brl: Decimal finito obrigatório")
    origens = pendencia.get("origens")
    if not isinstance(origens, list) or not origens:
        raise SaidaError("pendência.origens: ao menos uma evidência obrigatória")
    for origem in origens:
        if not isinstance(origem, Origem):
            raise SaidaError("pendência.origens: use Origem")
        if not isinstance(origem.arquivo, str):
            raise SaidaError("pendência.origens: arquivo deve ser texto")
        caminho = PurePosixPath(origem.arquivo)
        if (not origem.arquivo or not origem.arquivo.strip() or "\\" in origem.arquivo
                or caminho.is_absolute() or PureWindowsPath(origem.arquivo).drive
                or ".." in caminho.parts):
            raise SaidaError("pendência.origens: arquivo relativo à entrada obrigatório")
        if not isinstance(origem.ref, str) or not origem.ref.strip():
            raise SaidaError("pendência.origens: referência obrigatória")
        if not isinstance(origem.valor, Decimal) or not origem.valor.is_finite():
            raise SaidaError("pendência.origens: valor Decimal finito obrigatório")
    # Reutiliza exatamente a regra de soma/arredondamento do gravador.
    from src.core.saida import Saida

    Saida().emitir("pendencias", {k: pendencia[k] for k in
                  ("tipo", "ref_origem", "valor_brl", "motivo", "quem_decide")}, origens)

"""Leitor da Orbe (adquirente): `01_orbe_*.csv` + ajustes `06_orbe_ajustes_*.csv`.

CSV `;`, decimal vírgula, datas pt-BR. Encoding explícito: ASCII na origem (subconjunto do UTF-8).
Entrega **todas** as linhas, de qualquer tipo; filtrar o que é escopo é com a regra.
"""
from __future__ import annotations

import csv
from pathlib import Path

from src.core import normalize
from src.core.contratos import TransacaoOrbe

ENCODING = "utf-8"
PADRAO_PRINCIPAL = "01_orbe_*.csv"
PADRAO_AJUSTES = "06_orbe_ajustes_*.csv"

_OBRIGATORIAS = (
    "id_transacao", "data_movimento", "cod_estabelecimento", "nome_estabelecimento",
    "tipo_lancamento", "modalidade", "qtd_parcelas", "valor_bruto", "taxa_aplicada_pct",
)


def descobrir_arquivos(entrada: Path) -> list[Path]:
    """Principal (obrigatório) + ajustes (opcionais), ordenados por nome."""
    entrada = Path(entrada)
    principais = sorted(entrada.glob(PADRAO_PRINCIPAL))
    if not principais:
        raise FileNotFoundError(f"nenhum arquivo {PADRAO_PRINCIPAL} em {entrada}")
    return sorted({*principais, *entrada.glob(PADRAO_AJUSTES)}, key=lambda p: p.name)


def _texto(valor: str | None) -> str | None:
    return None if normalize._vazio(valor) else valor.strip()


def _ler_arquivo(caminho: Path, rotulo: str) -> list[TransacaoOrbe]:
    with caminho.open(encoding=ENCODING, newline="") as f:
        linhas = list(csv.reader(f, delimiter=";"))
    # cabeçalho localizado pelo conteúdo, não pelo número da linha
    pos = next((i for i, l in enumerate(linhas) if "id_transacao" in [c.strip() for c in l]), None)
    if pos is None:
        raise ValueError(f"{rotulo}: cabeçalho com `id_transacao` não encontrado")
    cab = [c.strip() for c in linhas[pos]]
    faltam = [c for c in _OBRIGATORIAS if c not in cab]
    if faltam:
        raise ValueError(f"{rotulo}: colunas ausentes {faltam}")

    saida: list[TransacaoOrbe] = []
    for numero, linha in enumerate(linhas[pos + 1:], start=pos + 2):
        if not any(c.strip() for c in linha):
            continue
        r = dict(zip(cab, linha))
        try:
            parcelas = _texto(r.get("qtd_parcelas"))
            id_ = r["id_transacao"].strip()
            if not id_:
                raise ValueError("id_transacao vazio")
            saida.append({
                "id_transacao": id_,
                "data_movimento": normalize.data(r["data_movimento"]),
                "ec": r["cod_estabelecimento"].strip(),
                "nome_origem": (_texto(r["nome_estabelecimento"]) or ""),
                "tipo_lancamento": r["tipo_lancamento"].strip(),
                "modalidade": _texto(r["modalidade"]),
                "qtd_parcelas": int(parcelas) if parcelas is not None else None,
                "valor_bruto": normalize.brl(r["valor_bruto"]),
                "taxa_aplicada_pct": normalize.pct(r["taxa_aplicada_pct"], fracao=False),
                "arquivo_origem": rotulo,
                "ref_origem": id_,
                "bandeira": _texto(r.get("bandeira")),
                "valor_taxa": normalize.brl(r.get("valor_taxa")),
                "valor_liquido": normalize.brl(r.get("valor_liquido")),
                "id_referencia": _texto(r.get("id_referencia")),
                "data_venda_original": normalize.data(r.get("data_venda_original")),
            })
        except ValueError as e:
            raise ValueError(f"{rotulo}, linha {numero}: {e}") from e
    return saida


def ler_orbe(entrada: Path) -> list[TransacaoOrbe]:
    """Lê todos os arquivos Orbe da pasta. `arquivo_origem` = caminho relativo (com `/`).

    `id_transacao` repetido, dentro de um arquivo ou entre arquivos, é erro explícito.
    """
    entrada = Path(entrada)
    transacoes: list[TransacaoOrbe] = []
    vistos: dict[str, str] = {}
    for caminho in descobrir_arquivos(entrada):
        rotulo = caminho.relative_to(entrada).as_posix()
        for t in _ler_arquivo(caminho, rotulo):
            if t["id_transacao"] in vistos:
                raise ValueError(
                    f"id_transacao {t['id_transacao']} repetido: {vistos[t['id_transacao']]} e {rotulo}"
                )
            vistos[t["id_transacao"]] = rotulo
            transacoes.append(t)
    return transacoes
"""Leitor da planilha de taxas contratadas (só a aba vigente) e gerador do cadastro mestre.

A planilha é mantida à mão: taxas em fração e em texto com `%`, CNPJ como número, vigência em
texto livre. Cabeçalho localizado pelo conteúdo; a aba `ANTIGO 2025 - nao usar` é ignorada.
Uma linha por vigência. Taxas em pontos percentuais; ausente = None (nunca zero).
"""
from __future__ import annotations

import re
import unicodedata
from pathlib import Path

import openpyxl
import yaml

from src.core import normalize
from src.core.contratos import ContratoTaxa

ABA = "taxas vigentes"

# cabeçalho normalizado -> campo interno
_COLUNAS = {
    "lojista": "lojista",
    "cnpj": "cnpj",
    "ec orbe": "ec",
    "debito": "DEBITO",
    "credito a vista": "CREDITO_A_VISTA",
    "cred. 2-6x": "CREDITO_2_6",
    "cred. 7-12x": "CREDITO_7_12",
    "pix": "PIX",
    "vigencia": "vigencia",
    "obs": "obs",
}
_FAIXAS = ("DEBITO", "CREDITO_A_VISTA", "CREDITO_2_6", "CREDITO_7_12", "PIX")
_DATA = re.compile(r"\d{2}/\d{2}/\d{4}")


def _chave(texto) -> str:
    t = unicodedata.normalize("NFKD", str(texto)).encode("ascii", "ignore").decode()
    return re.sub(r"\s+", " ", t).strip().lower()


def _achar_aba(wb: openpyxl.Workbook):
    for ws in wb.worksheets:
        if _chave(ws.title) == ABA:
            return ws
    raise ValueError(f"aba '{ABA}' não encontrada; abas: {wb.sheetnames}")


def _achar_cabecalho(ws) -> tuple[int, dict[str, int]]:
    """(linha física, {campo: índice da coluna}) da primeira linha que tem Lojista e CNPJ."""
    for numero, linha in enumerate(ws.iter_rows(values_only=True), start=1):
        mapa = {_COLUNAS[_chave(v)]: i for i, v in enumerate(linha)
                if v is not None and _chave(v) in _COLUNAS}
        if "lojista" in mapa and "cnpj" in mapa:
            return numero, mapa
    raise ValueError("cabeçalho (Lojista, CNPJ) não encontrado na aba de taxas vigentes")


def _texto(x) -> str | None:
    return None if normalize._vazio(x) else str(x).strip()


def _ec(x) -> str | None:
    if normalize._vazio(x):
        return None
    if isinstance(x, float) and x == int(x):
        x = int(x)
    return str(x).strip()


def interpretar_vigencia(x) -> tuple[str | None, str | None]:
    """Texto de vigência -> (início, fim) ISO, ambos inclusivos; None = limite aberto."""
    if normalize._vazio(x):
        return None, None
    if not isinstance(x, str):
        return normalize.data(x), None  # data solta (célula de data): início
    datas = [normalize.data(d) for d in _DATA.findall(x)]
    t = _chave(x)
    if len(datas) == 2:
        return datas[0], datas[1]
    if len(datas) == 1:
        if t.startswith("ate"):
            return None, datas[0]
        return datas[0], None  # "a partir de", "desde" ou data solta
    raise ValueError(f"vigência não reconhecida: {x!r}")


def ler_taxas(caminho: Path, arquivo_origem: str | None = None) -> list[ContratoTaxa]:
    """Contratos da aba vigente, um por linha (vigência). `arquivo_origem` default = nome do arquivo."""
    caminho = Path(caminho)
    rotulo = arquivo_origem or caminho.name
    wb = openpyxl.load_workbook(caminho, data_only=True, read_only=False)
    ws = _achar_aba(wb)
    cab, col = _achar_cabecalho(ws)

    def celula(linha, campo):
        i = col.get(campo)
        return linha[i] if i is not None and i < len(linha) else None

    contratos: list[ContratoTaxa] = []
    for numero, linha in enumerate(ws.iter_rows(min_row=cab + 1, values_only=True), start=cab + 1):
        lojista = _texto(celula(linha, "lojista"))
        if lojista is None or lojista.startswith("*"):  # linha vazia ou nota de rodapé
            continue
        ref = f"{ws.title}!L{numero}"
        try:
            cnpj = normalize.cnpj(celula(linha, "cnpj"))
            if cnpj is None:
                raise ValueError("CNPJ vazio")
            ini, fim = interpretar_vigencia(celula(linha, "vigencia"))
            obs = _chave(celula(linha, "obs") or "")
            contratos.append({
                "cnpj": cnpj,
                "lojista": lojista,
                "ec": _ec(celula(linha, "ec")),
                "ativo": "inativ" not in obs,
                "vigencia_inicio": ini,
                "vigencia_fim": fim,
                "taxas_pct": {f: normalize.pct(celula(linha, f), fracao=True) for f in _FAIXAS},
                "arquivo_origem": rotulo,
                "ref_origem": ref,
            })
        except ValueError as e:
            raise ValueError(f"{rotulo}, {ref}: {e}") from e
    return contratos


# --- cadastro mestre (EC -> CNPJ) -------------------------------------------------------------

_CABECALHO_YAML = """\
# Cadastro mestre de lojistas (EC <-> CNPJ).
# Gerado por regra EXATA (EC da planilha de taxas) e completado só com confirmação humana.
# Nunca por fuzzy match de nome. Regerar: python -m src.ingest.taxas <planilha.xlsx> config/lojistas.yaml
# A regeração só ACRESCENTA ECs novos; entradas existentes (inclusive confirmadas à mão) são mantidas.
"""


class _DumperAspas(yaml.SafeDumper):
    """Todo texto entre aspas: CNPJ/EC com zero à esquerda nunca viram número em outro leitor de YAML."""


_DumperAspas.add_representer(str, lambda d, v: d.represent_scalar("tag:yaml.org,2002:str", v, style='"'))


def gerar_cadastro(contratos: list[ContratoTaxa]) -> dict[str, dict[str, str]]:
    """EC -> {cnpj, lojista}, só de contratos com EC. Mesmo EC com CNPJ diferente é erro."""
    cadastro: dict[str, dict[str, str]] = {}
    for c in contratos:
        if c["ec"] is None:
            continue
        atual = cadastro.setdefault(c["ec"], {"cnpj": c["cnpj"], "lojista": c["lojista"]})
        if atual["cnpj"] != c["cnpj"]:
            raise ValueError(f"EC {c['ec']} com CNPJs diferentes: {atual['cnpj']} e {c['cnpj']} ({c['ref_origem']})")
    return cadastro


def atualizar_cadastro_yaml(contratos: list[ContratoTaxa], destino: Path) -> int:
    """Acrescenta ao YAML os ECs ainda ausentes. Devolve quantos entraram; conflito de CNPJ é erro."""
    destino = Path(destino)
    existente = {}
    if destino.exists():
        existente = (yaml.safe_load(destino.read_text(encoding="utf-8")) or {}).get("lojistas") or {}
    novos = gerar_cadastro(contratos)
    for ec, dados in novos.items():
        if ec in existente and existente[ec]["cnpj"] != dados["cnpj"]:
            raise ValueError(f"EC {ec}: cadastro tem {existente[ec]['cnpj']}, planilha tem {dados['cnpj']}")
    acrescentar = {ec: d for ec, d in novos.items() if ec not in existente}
    final = {**existente, **acrescentar}
    corpo = yaml.dump({"lojistas": final}, Dumper=_DumperAspas, allow_unicode=True, sort_keys=True, default_flow_style=False)
    destino.write_text(_CABECALHO_YAML + corpo, encoding="utf-8")
    return len(acrescentar)


if __name__ == "__main__":
    import sys

    if len(sys.argv) != 3:
        sys.exit("uso: python -m src.ingest.taxas <planilha.xlsx> <lojistas.yaml>")
    n = atualizar_cadastro_yaml(ler_taxas(Path(sys.argv[1])), Path(sys.argv[2]))
    print(f"{n} lojista(s) acrescentado(s) em {sys.argv[2]}")
"""Comissão de checkout (nível Mínimo): só `VENDA`, pela taxa **contratada**.

Regra (CONFIRMADO, P1): comissão = valor_bruto x taxa_contratada, a taxa inteira, sem descontar o
custo da Orbe e sem usar a taxa aplicada. Arredondamento por venda (ROUND_HALF_UP) e o total do
lojista é a soma das linhas arredondadas (HIPOTESES.md §2).

Função pura: recebe registros, devolve registros com as origens. Não grava arquivo e não conhece o
gravador (a fronteira com `core/saida.py` está em CONTRATO_TECNICO_MINIMO.md §1). Nada de EC, CNPJ
ou nome de lojista aqui: identidade vem do cadastro e taxas vêm da planilha.

Cada venda aparece exatamente uma vez: numa origem de comissão ou numa pendência bloqueante.
"""
from __future__ import annotations

import re
import unicodedata
from collections import Counter
from decimal import Decimal

from src.core import normalize
from src.core.contratos import (
    ComissaoCalculada,
    ContratoTaxa,
    Origem,
    PendenciaCalculada,
    ResultadoCheckout,
    TransacaoOrbe,
)

CENTO = Decimal("100")
TIPO_VENDA = "VENDA"

# (tipo, quem_decide) de cada problema, conforme CONTRATO_TECNICO_MINIMO.md §3
_QUEM = {
    "CADASTRO_NAO_RESOLVIDO": "Financeiro",
    "VENDA_INVALIDA": "Financeiro",
    "CONTRATO_AUSENTE": "Comercial",
    "CONTRATO_INATIVO": "Comercial",
    "VIGENCIA_SEM_COBERTURA": "Comercial",
    "TAXA_AUSENTE": "Comercial",
    "CONTRATO_AMBIGUO": "Comercial",
}


class _Problema(tuple):
    """(tipo, quem_decide, motivo)"""

    def __new__(cls, tipo: str, motivo: str, quem: str | None = None):
        return super().__new__(cls, (tipo, quem or _QUEM[tipo], motivo))


def _chave(texto) -> str:
    t = unicodedata.normalize("NFKD", str(texto)).encode("ascii", "ignore").decode()
    return re.sub(r"\s+", " ", t).strip().upper()


def _fmt(valor: Decimal) -> str:
    """Dinheiro em pt-BR para texto de motivo: 5480.00 -> '5.480,00'."""
    inteiro, _, frac = f"{valor:.2f}".partition(".")
    sinal = "-" if inteiro.startswith("-") else ""
    inteiro = inteiro.lstrip("-")
    return f"{sinal}{int(inteiro):,}".replace(",", ".") + f",{frac}"


def faixa_da_venda(modalidade: str | None, parcelas: int | None) -> str:
    """Faixa de taxa (chave de `taxas_pct`) da venda. Levanta ValueError se modalidade/parcelas não fecham."""
    mod = _chave(modalidade) if modalidade else ""
    if mod in ("DEBITO", "PIX", "CREDITO A VISTA"):
        if parcelas != 1:
            raise ValueError(f"modalidade {mod} com {parcelas!r} parcela(s); esperado 1")
        return {"DEBITO": "DEBITO", "PIX": "PIX", "CREDITO A VISTA": "CREDITO_A_VISTA"}[mod]
    if mod == "CREDITO PARCELADO":
        if parcelas is not None and 2 <= parcelas <= 6:
            return "CREDITO_2_6"
        if parcelas is not None and 7 <= parcelas <= 12:
            return "CREDITO_7_12"
        raise ValueError(f"crédito parcelado com {parcelas!r} parcela(s); esperado de 2 a 12")
    raise ValueError(f"modalidade desconhecida: {modalidade!r}")


def _cobre(c: ContratoTaxa, data: str) -> bool:
    """Vigência com limites inclusivos; None = limite aberto. Datas ISO comparam como texto."""
    return (c["vigencia_inicio"] is None or c["vigencia_inicio"] <= data) and (
        c["vigencia_fim"] is None or data <= c["vigencia_fim"]
    )


def _checar_regras(regras: dict) -> dict:
    cfg = (regras or {}).get("checkout", {}) or {}
    if cfg.get("base_comissao", "taxa_contratada") != "taxa_contratada":
        raise ValueError(f"base_comissao não suportada: {cfg['base_comissao']!r}")
    if cfg.get("vigencia_venda", "data_movimento") != "data_movimento":
        raise ValueError(f"vigencia_venda não suportada: {cfg['vigencia_venda']!r}")
    return cfg


def _problema_de_identidade(t: TransacaoOrbe, rotas: dict) -> _Problema:
    """EC fora do cadastro. Roteamento especial vem de `checkout.ec_sem_cadastro` (config), senão genérico."""
    rota = rotas.get(t["ec"])
    if rota:
        return _Problema(rota["tipo"], f"EC {t['ec']} ({t['nome_origem']}): {rota['motivo']}", rota.get("quem_decide"))
    return _Problema(
        "CADASTRO_NAO_RESOLVIDO",
        f"EC {t['ec']} ({t['nome_origem']}) não consta no cadastro de lojistas; "
        "o nome não é usado para identificar o lojista.",
    )


def _resolver_contrato(t, cnpj_cadastro, por_ec) -> tuple[ContratoTaxa | None, _Problema | None]:
    candidatos = por_ec.get(t["ec"], [])
    if not candidatos:
        return None, _Problema("CONTRATO_AUSENTE", f"EC {t['ec']} está no cadastro mas não tem contrato de taxas na planilha vigente.")
    divergentes = sorted({c["ref_origem"] for c in candidatos if c["cnpj"] != cnpj_cadastro})
    if divergentes:
        return None, _Problema(
            "CONTRATO_AMBIGUO",
            f"CNPJ do cadastro ({cnpj_cadastro}) difere do CNPJ da planilha para o EC {t['ec']} ({', '.join(divergentes)}).",
        )
    cobrindo = [c for c in candidatos if _cobre(c, t["data_movimento"])]
    if not cobrindo:
        if not any(c["ativo"] for c in candidatos):
            return None, _Problema("CONTRATO_INATIVO", f"Contrato do EC {t['ec']} está inativo na planilha.")
        return None, _Problema(
            "VIGENCIA_SEM_COBERTURA",
            f"Nenhuma vigência do EC {t['ec']} cobre a data {t['data_movimento']}.",
        )
    if len(cobrindo) > 1:
        refs = ", ".join(c["ref_origem"] for c in cobrindo)
        return None, _Problema("CONTRATO_AMBIGUO", f"Mais de uma vigência cobre {t['data_movimento']} para o EC {t['ec']} ({refs}).")
    if not cobrindo[0]["ativo"]:
        return None, _Problema("CONTRATO_INATIVO", f"Contrato do EC {t['ec']} está inativo na planilha ({cobrindo[0]['ref_origem']}).")
    return cobrindo[0], None


def _avaliar_venda(t, cadastro, por_ec, rotas):
    """Devolve (comissão, contrato, None) ou (None, None, [problemas])."""
    problemas: list[_Problema] = []
    contrato = None
    faixa = None

    bruto = t["valor_bruto"]
    if bruto is None or bruto <= 0:
        problemas.append(_Problema("VENDA_INVALIDA", f"Venda com valor bruto ausente ou não positivo ({bruto})."))
    try:
        faixa = faixa_da_venda(t["modalidade"], t["qtd_parcelas"])
    except ValueError as e:
        problemas.append(_Problema("VENDA_INVALIDA", f"Não foi possível definir a faixa de taxa: {e}."))

    if t["ec"] not in cadastro:
        problemas.insert(0, _problema_de_identidade(t, rotas))
    else:
        contrato, p = _resolver_contrato(t, cadastro[t["ec"]]["cnpj"], por_ec)
        if p:
            problemas.insert(0, p)
        elif faixa and contrato["taxas_pct"][faixa] is None:
            problemas.append(_Problema(
                "TAXA_AUSENTE",
                f"Contrato {contrato['ref_origem']} não tem taxa para a faixa {faixa}.",
            ))

    if problemas:
        return None, None, problemas
    taxa = contrato["taxas_pct"][faixa]
    return normalize.q2(bruto * taxa / CENTO), contrato, None


def _pendencia_de_venda(t: TransacaoOrbe, problemas: list[_Problema]) -> PendenciaCalculada:
    bruto = t["valor_bruto"] if t["valor_bruto"] is not None else Decimal("0")
    base = f"Valor da pendência = valor bruto da venda (R$ {_fmt(bruto)}), não a comissão, que ainda é desconhecida. A venda não entrou na comissão."
    tipo, quem, _ = problemas[0]
    motivo = " | ".join(p[2] for p in problemas) + " " + base
    return {
        "tipo": tipo,
        "ref_origem": t["ref_origem"],
        "valor_brl": bruto,
        "motivo": motivo,
        "quem_decide": quem,
        "origens": [Origem(t["arquivo_origem"], t["ref_origem"], bruto)],
    }


def _pendencias_cadastrais(contratos: list[ContratoTaxa]) -> list[PendenciaCalculada]:
    """Linhas da planilha com checkout previsto e problema de cadastro (valor 0, aponta para a linha)."""
    saida: list[PendenciaCalculada] = []
    for c in contratos:
        if all(v is None for v in c["taxas_pct"].values()):
            continue  # só remessa: não é problema de checkout
        if c["ec"] is None:
            tipo, motivo = "CADASTRO_NAO_RESOLVIDO", (
                f"{c['lojista']} (CNPJ {c['cnpj']}) tem taxas de cartão/Pix na planilha mas não tem EC da Orbe; "
                "vendas só serão ligadas a este contrato depois que uma pessoa confirmar o EC."
            )
        elif not c["ativo"]:
            tipo, motivo = "CONTRATO_INATIVO", (
                f"{c['lojista']} (EC {c['ec']}) está marcado como inativo na planilha; "
                "vendas desse EC não geram comissão até o Comercial reativar o contrato."
            )
        else:
            continue
        saida.append({
            "tipo": tipo,
            "ref_origem": c["ref_origem"],
            "valor_brl": Decimal("0"),
            "motivo": motivo + " Pendência cadastral: valor zero.",
            "quem_decide": _QUEM[tipo],
            "origens": [Origem(c["arquivo_origem"], c["ref_origem"], Decimal("0"))],
        })
    return saida


def calcular_checkout(
    transacoes: list[TransacaoOrbe],
    contratos: list[ContratoTaxa],
    cadastro: dict[str, dict[str, str]],
    competencia: str,
    regras: dict,
) -> ResultadoCheckout:
    """Comissão de checkout das vendas, por lojista (CNPJ), mais pendências e resumo de conservação."""
    cfg = _checar_regras(regras)
    rotas = cfg.get("ec_sem_cadastro") or {}
    if not re.fullmatch(r"\d{4}-(0[1-9]|1[0-2])", competencia or ""):
        raise ValueError(f"competência inválida (esperado AAAA-MM): {competencia!r}")
    fora = [t["id_transacao"] for t in transacoes if t["data_movimento"][:7] != competencia]
    if fora:
        raise ValueError(
            f"{len(fora)} transação(ões) fora da competência {competencia}, ex.: {', '.join(fora[:3])}"
        )

    cad = {ec: {"cnpj": normalize.cnpj(d["cnpj"]), "lojista": d["lojista"]} for ec, d in cadastro.items()}
    por_ec: dict[str, list[ContratoTaxa]] = {}
    for c in contratos:
        if c["ec"] is not None:
            por_ec.setdefault(c["ec"], []).append(c)

    acum: dict[str, dict] = {}
    pendencias: list[PendenciaCalculada] = []
    fora_escopo: Counter[str] = Counter()
    vendas = processadas = 0

    for t in transacoes:
        if _chave(t["tipo_lancamento"]) != TIPO_VENDA:
            fora_escopo[t["tipo_lancamento"]] += 1
            continue
        vendas += 1
        comissao, contrato, problemas = _avaliar_venda(t, cad, por_ec, rotas)
        if problemas:
            pendencias.append(_pendencia_de_venda(t, problemas))
            continue
        processadas += 1
        ident = cad[t["ec"]]
        a = acum.setdefault(ident["cnpj"], {"lojista": ident["lojista"], "total": Decimal("0"), "origens": [], "contratos": {}})
        a["total"] += comissao
        a["origens"].append(Origem(t["arquivo_origem"], t["ref_origem"], comissao))
        a["contratos"].setdefault((contrato["arquivo_origem"], contrato["ref_origem"]), None)

    comissoes: list[ComissaoCalculada] = [
        {
            "cnpj": cnpj,
            "lojista": a["lojista"],
            "linha_negocio": "CHECKOUT",
            "comissao_brl": a["total"],
            "origens": a["origens"],
            "contratos_utilizados": [{"arquivo_origem": f, "ref_origem": r} for f, r in a["contratos"]],
        }
        for cnpj, a in sorted(acum.items())
    ]
    pendencias += _pendencias_cadastrais(contratos)

    return {
        "comissoes": comissoes,
        "pendencias": pendencias,
        "resumo": {
            "total_orbe": len(transacoes),
            "vendas_total": vendas,
            "vendas_processadas": processadas,
            "vendas_bloqueadas": vendas - processadas,
            "fora_escopo_por_tipo": dict(sorted(fora_escopo.items())),
            "contagens_por_arquivo": dict(sorted(Counter(t["arquivo_origem"] for t in transacoes).items())),
        },
    }
